CREATE TABLE "account_movements" (
	"id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "account_movements_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 2147483647 START WITH 1 CACHE 1),
	"user_id" integer NOT NULL,
	"kind" text NOT NULL,
	"date" text NOT NULL,
	"amount_cents" integer NOT NULL,
	"description" text NOT NULL,
	"settlement_id" integer,
	"invoice_id" integer,
	"one_time_id" integer,
	"box_tx_id" integer,
	"created_at" text DEFAULT (to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) NOT NULL,
	CONSTRAINT "account_movements_settlement_id_unique" UNIQUE("settlement_id"),
	CONSTRAINT "account_movements_invoice_id_unique" UNIQUE("invoice_id"),
	CONSTRAINT "account_movements_one_time_id_unique" UNIQUE("one_time_id"),
	CONSTRAINT "account_movements_box_tx_id_unique" UNIQUE("box_tx_id"),
	CONSTRAINT "account_movements_kind" CHECK ("account_movements"."kind" IN ('opening', 'adjustment', 'income', 'expense', 'invoice', 'one_time', 'box')),
	CONSTRAINT "account_movements_date_fmt" CHECK ("account_movements"."date" ~ '^[0-9]{4}-[0-1][0-9]-[0-3][0-9]$'),
	CONSTRAINT "account_movements_amount_nonzero" CHECK ("account_movements"."amount_cents" <> 0 OR "account_movements"."kind" = 'opening')
);
