-- O saldo que cada conta já tinha informado vira o "Saldo inicial" do extrato.
INSERT INTO "account_movements" ("user_id", "kind", "date", "amount_cents", "description")
SELECT "user_id", 'opening', COALESCE("account_balance_date", to_char(now() at time zone 'America/Sao_Paulo', 'YYYY-MM-DD')), "account_balance_cents", 'Saldo inicial'
FROM "settings"
WHERE "account_balance_cents" IS NOT NULL;
